export const entries: EncyclopediaEntry[] = [
  { slug:"platone", id:"AUT-000011", kind:"autore", title:"Platone", subtitle:"Dialoghi, conoscenza e forme della vita politica", area:"Grecia antica", period:"IV secolo a.C.", summary:"Filosofo ateniese (circa 427–347 a.C.), autore di dialoghi che hanno segnato profondamente la storia della filosofia antica.", sections:[
    {heading:"Profilo storico",paragraphs:["Platone visse ad Atene tra la fine del V e la prima metà del IV secolo a.C. Fu legato a Socrate e fondò una comunità di studio nota come Accademia. La sua opera è composta in gran parte da dialoghi, nei quali la ricerca procede attraverso domande, confutazioni e argomentazioni.","La cronologia e l'interpretazione di alcuni dialoghi restano oggetto di discussione specialistica. È opportuno distinguere i dati biografici attestati dalle ricostruzioni dottrinali."]},
    {heading:"Temi e problemi",paragraphs:["Tra i temi ricorrenti figurano conoscenza, giustizia, virtù, anima, linguaggio, educazione e organizzazione della città. La teoria delle forme è centrale in numerosi dialoghi, ma il suo ruolo varia secondo i contesti argomentativi.","La forma dialogica non è un semplice involucro letterario: mette in scena il confronto tra posizioni e invita il lettore a seguire il lavoro della ragione."]},
    {heading:"Ricezione e confronti",paragraphs:["Le opere platoniche furono commentate e reinterpretate in contesti greci, tardo-antichi, bizantini, arabi, ebraici, latini e moderni. Ogni ricezione va ricostruita attraverso testi, traduzioni e contesti specifici."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["La forma dialogica impedisce di trattare ogni battuta di Socrate come una tesi definitiva di Platone. Le forme sono argomentate in modi diversi nel Fedone, nella Repubblica e nel Parmenide, che ne esamina anche le difficoltà. Un percorso può accostare Apologia e Critone, Menone e Fedone, Simposio e Fedro, Repubblica e Parmenide. La cronologia tradizionale dei dialoghi resta orientativa, non una sequenza certa di conversioni dottrinali."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["Un nodo di ricerca riguarda il rapporto tra oralità, scrittura e insegnamento. Nel Fedro la critica alla scrittura non equivale a un rifiuto dei testi: mette in scena i limiti di un discorso che non può rispondere alle domande del lettore. Il problema delle cosiddette dottrine non scritte e delle testimonianze indirette va affrontato distinguendo ciò che attestano le fonti antiche da ciò che ricostruiscono gli studiosi moderni.","Per un confronto interno al corpus, il Sofista è particolarmente utile: ridefinisce il non-essere attraverso differenza e predicazione, evitando di ridurlo al nulla assoluto. Il confronto con il Parmenide mostra che la filosofia platonica include anche l'esame critico delle proprie ipotesi. Una scheda avanzata dovrebbe quindi collegare ogni tesi al dialogo, alla scena argomentativa e alle interpretazioni concorrenti."]}], thoughtAnalysis:["La ricerca platonica nasce dalla distinzione fra opinione e conoscenza, apparenza sensibile e realtà intelligibile. I dialoghi non offrono un sistema dogmatico già pronto: attraverso domande, confutazioni e aporie, Socrate mette alla prova definizioni e convinzioni. La dialettica è insieme metodo razionale e formazione dell’anima. La teoria delle forme sostiene che le cose sensibili sono conoscibili in quanto partecipano di strutture intelligibili, ma non costituisce una dottrina immobile: il Parmenide ne esamina le difficoltà, mentre il Sofista ripensa essere, differenza e non-essere. Ogni tesi va ricostruita nel dialogo che la ospita, considerando interlocutori, obiezioni e sviluppo argomentativo.","Metafisica, etica, psicologia e politica sono inseparabili. Nella Repubblica la giustizia è ordine dell’anima e, per analogia, della città; il bene orienta conoscenza e azione. Nei dialoghi sull’amore il desiderio può diventare elevazione conoscitiva. Non ogni affermazione di Socrate coincide automaticamente con la posizione dell’autore. Anche il rapporto fra oralità e scrittura e il problema delle dottrine non scritte richiedono cautela filologica. Il pensiero platonico è un’indagine aperta, nella quale conoscere il vero significa anche trasformare il modo di vivere."], tags:["Grecia","metafisica","conoscenza","etica","politica"], related:[{label:"Aristotele",slug:"aristotele",relation:"allievo e interlocutore critico"}], bibliography:[{label:"Platone, Plato: Complete Works, a cura di John M. Cooper e D. S. Hutchinson, Hackett, 1997.",type:"Edizione di riferimento",note:"Edizione inglese complessiva con introduzioni e note; include anche opere spurie e dubbie, da distinguere dal corpus autentico. Per il lettore italiano: Platone, Opere complete, Laterza, collezione ebook del 2019 (39 opere; comprende anche scritti dubbi e spuri). Per il testo greco resta un riferimento storico l’edizione di John Burnet, Platonis Opera, 5 voll., Oxford Classical Texts, 1900–1907."}], keyTerms: [{"term":"eidos / idea","explanation":"Forma intelligibile che rende conoscibile ciò che le cose sensibili sono."},{"term":"anamnesi","explanation":"Modello della conoscenza come riconoscimento dell'intelligibile."},{"term":"dialettica","explanation":"Ricerca razionale che esamina ipotesi e connessioni tra le forme."},{"term":"polis","explanation":"Comunità politica la cui giustizia è indagata nella Repubblica."}], works: [{"title":"Apologia di Socrate","note":"Rappresentazione della pratica filosofica socratica."},{"title":"Fedone","note":"Dialogo sull'anima, la morte e la conoscenza delle forme."},{"title":"Repubblica","note":"Indagine su giustizia, educazione e ordinamento politico."},{"title":"Parmenide","note":"Esame critico delle difficoltà della teoria delle forme."},{"title":"Fedro","note":"Riflessione su amore, anima, retorica e scrittura."}], timeline: [{"date":"circa 427 a.C.","event":"Nascita ad Atene; data tradizionale approssimativa."},{"date":"399 a.C.","event":"Morte di Socrate."},{"date":"IV secolo a.C.","event":"Attività dell'Accademia; cronologia dei dialoghi discussa."},{"date":"circa 347 a.C.","event":"Morte di Platone."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"aristotele", id:"AUT-000012", kind:"autore", title:"Aristotele", subtitle:"Logica, natura, metafisica ed etica", area:"Grecia antica", period:"IV secolo a.C.", summary:"Filosofo e studioso greco (384–322 a.C.) la cui opera comprende indagini di logica, filosofia della natura, metafisica, etica, politica e poetica.", sections:[
    {heading:"Profilo storico",paragraphs:["Nato a Stagira, Aristotele trascorse un periodo nell'Accademia di Platone e in seguito fondò ad Atene una propria scuola, il Liceo. I testi conservati sono in larga parte trattati o materiali didattici, trasmessi attraverso una complessa storia manoscritta.","La ricostruzione del corpus e della sua organizzazione resta materia di ricerca filologica."]},
    {heading:"Temi e problemi",paragraphs:["Aristotele sviluppò strumenti di analisi del ragionamento, una teoria delle cause, una riflessione sulla sostanza e una concezione teleologica della natura. Nell'etica indagò felicità, virtù e abitudine; nella politica studiò le forme della comunità e dei regimi.","Le discipline aristoteliche sono connesse, ma non coincidono con la moderna divisione accademica dei saperi."]},
    {heading:"Ricezione e confronti",paragraphs:["Il corpus aristotelico fu tradotto, commentato e discusso in greco, siriaco, arabo, ebraico e latino. Le tradizioni filosofiche islamiche, ebraiche e cristiane ne elaborarono letture differenti."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Sostanza, cause, potenza e atto formano una rete concettuale che cambia funzione secondo l’indagine. Anche il metodo varia: la ricerca naturale parte dai fenomeni, mentre la dimostrazione richiede premesse adeguate. L’etica non può pretendere la precisione della matematica. Un percorso può passare da Categorie e Analitici posteriori a Fisica, De anima e Metafisica, quindi a Etica Nicomachea e Politica. I trattati conservati riflettono una complessa storia redazionale."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["Un problema filologico centrale è la forma del corpus: molti scritti hanno l'aspetto di materiali di lezione, rinvii interni e stratificazioni. La tradizionale organizzazione in opere non deve far pensare che Aristotele abbia pubblicato ogni trattato nella forma oggi letta. Anche la relazione tra scritti essoterici perduti e trattati conservati resta importante per ricostruire il suo progetto filosofico.","Per studiare la metafisica è utile seguire la pluralità dei significati dell'essere in Metafisica Γ e il ruolo della sostanza nei libri Ζ e Η; per l'etica, leggere insieme i libri sull'amicizia e sulla saggezza pratica evita di ridurre la virtù al solo giusto mezzo. I rinvii interni tra discipline sono parte dell'argomentazione, non semplici rimandi enciclopedici."]}], thoughtAnalysis:["Aristotele distingue le scienze secondo oggetti e metodi, collegandole con la domanda su che cosa significhi spiegare. La logica studia predicazione e inferenza; la fisica indaga movimento e cause; la metafisica esamina l’essere in quanto essere e la sostanza. Le quattro cause, materiale, formale, efficiente e finale, articolano differenti risposte alla domanda del perché. Potenza e atto spiegano il mutamento come processo di realizzazione. L’essere si dice in più modi, ma i significati fanno riferimento alla sostanza. La dimostrazione scientifica richiede principi appropriati, mentre l’etica non può avere la precisione della matematica: il metodo deve rispettare la natura dell’oggetto.","La felicità è attività secondo virtù lungo una vita compiuta, non un’emozione passeggera. Le virtù si formano con l’abitudine e diventano disposizioni di scelta; la phronesis giudica il particolare e individua il giusto mezzo, che non è una media aritmetica. L’amicizia è parte della vita buona. La politica studia la comunità e i regimi in rapporto al bene comune, pur riflettendo i limiti della cittadinanza antica. Il corpus ha una storia redazionale complessa: non va immaginato come un libro unitario pubblicato dall’autore nella forma oggi disponibile."], tags:["Grecia","logica","natura","metafisica","etica"], related:[{label:"Platone",slug:"platone",relation:"maestro e interlocutore critico"}], bibliography:[{label:"Aristotele, The Complete Works of Aristotle: The Revised Oxford Translation, a cura di Jonathan Barnes, 2 voll., Princeton University Press, 1984.",type:"Edizione di riferimento",note:"Raccolta di riferimento per la traduzione inglese del corpus. Per il lettore italiano: Aristotele, Opere, Laterza, collezione ebook del 2019 (20 opere, con traduzioni di studiosi diversi). Per l’Etica Nicomachea si può usare anche l’edizione italiana a cura di Carlo Natali, Laterza, 1999 e ristampe successive; per il testo greco resta fondamentale Immanuel Bekker, Aristotelis Opera, 1831."}], keyTerms: [{"term":"ousia","explanation":"Sostanza o realtà primaria; il significato varia nei diversi trattati."},{"term":"aitia","explanation":"Causa o spiegazione: materiale, formale, efficiente e finale."},{"term":"dynamis / energeia","explanation":"Potenza e atto, strumenti per descrivere mutamento e realizzazione."},{"term":"phronesis","explanation":"Saggezza pratica che orienta la deliberazione."},{"term":"eudaimonia","explanation":"Fioritura o vita riuscita, fine dell'indagine etica."}], works: [{"title":"Categorie","note":"Analisi delle forme fondamentali di predicazione."},{"title":"Fisica","note":"Studio della natura, del movimento e delle cause."},{"title":"De anima","note":"Indagine sull'anima come principio della vita."},{"title":"Metafisica","note":"Ricerca dell'essere in quanto essere e delle sostanze."},{"title":"Etica Nicomachea","note":"Trattazione di felicità, virtù, scelta e amicizia."},{"title":"Politica","note":"Analisi della comunità civica e dei regimi."}], timeline: [{"date":"384 a.C.","event":"Nascita a Stagira."},{"date":"367/366 a.C.","event":"Ingresso nell'Accademia, secondo la cronologia tradizionale."},{"date":"343/342 a.C.","event":"Soggiorno presso la corte macedone."},{"date":"335/334 a.C.","event":"Avvio dell'attività del Liceo ad Atene."},{"date":"322 a.C.","event":"Morte a Calcide."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"confucio", id:"AUT-000013", kind:"autore", title:"Confucio", subtitle:"Formazione morale, riti e responsabilità politica", area:"Cina", period:"VI–V secolo a.C.", summary:"Maestro della Cina antica (tradizionalmente 551–479 a.C.), figura fondamentale per la tradizione confuciana e per le riflessioni su educazione, virtù e ordine sociale.", sections:[
    {heading:"Profilo storico",paragraphs:["La figura di Confucio è conosciuta soprattutto attraverso testi trasmessi e rielaborati da generazioni di discepoli. I Dialoghi (Lunyu) sono una fonte centrale, ma non una trascrizione immediata e unitaria delle sue parole.","La formazione storica del corpus e la pluralità delle correnti confuciane richiedono attenzione alle diverse fasi della tradizione."]},
    {heading:"Temi e problemi",paragraphs:["La riflessione attribuita a Confucio insiste sulla coltivazione di sé, sull'apprendimento, sulla benevolenza (ren), sulla correttezza rituale (li) e sull'esempio morale di chi governa.","I concetti confuciani hanno significati storicamente situati e non corrispondono automaticamente a nozioni moderne come individuo, Stato o religione."]},
    {heading:"Ricezione e confronti",paragraphs:["Il confucianesimo si è trasformato attraverso scuole, commentari, istituzioni educative e dibattiti politici. La sua storia comprende sviluppi classici, imperiali e moderni."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Ren (benevolenza), li (riti), yi (rettitudine) e xiao (rispetto filiale) non sono regole isolate: il loro significato emerge nelle relazioni. Il rito educa comportamento ed emozioni, mentre la benevolenza impedisce che la correttezza esteriore diventi formalismo. Il junzi è una persona resa esemplare dalla formazione. Nei Dialoghi le risposte variano in base all’interlocutore; commentari e manoscritti paralleli mostrano una storia di trasmissione più articolata di una semplice raccolta di detti."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["Il corpus dei Lunyu non esaurisce il confucianesimo antico. Il Mengzi sviluppa una riflessione sulla bontà della natura umana e sulla coltivazione delle disposizioni morali; lo Xunzi difende invece il ruolo formativo dei riti e dell'educazione contro le inclinazioni spontanee. Il confronto mostra che la tradizione si costituisce anche attraverso controversie, non attraverso la ripetizione uniforme di un insegnamento originario.","Un approfondimento dovrebbe distinguere il Confucio storico, la figura costruita dalla memoria dei discepoli e il maestro canonico delle epoche imperiali. Le istituzioni educative e gli esami imperiali trasformarono la funzione dei classici. È quindi necessario separare il confucianesimo pre-imperiale, le sintesi Han e le successive elaborazioni neoconfuciane."]}], thoughtAnalysis:["Il pensiero confuciano riguarda la formazione morale entro relazioni concrete. Ren, benevolenza o umanità, si manifesta nella considerazione per gli altri; li indica riti e pratiche che educano gesti, emozioni e comportamenti. Il rito non è formalismo: rende possibile una convivenza ordinata, ma senza benevolenza diventa vuota osservanza. Yi è rettitudine, capacità di riconoscere ciò che è appropriato; lo studio trasforma il carattere e non si riduce ad accumulo di nozioni. Il junzi, persona esemplare, è il risultato di apprendimento e autocorrezione, non un privilegio di nascita.","Il buon governo dipende dall’esempio morale più che dalla sola coercizione: le sanzioni possono imporre conformità, non generare una disposizione interiore. Nei Dialoghi le risposte mutano secondo l’interlocutore, segno di un insegnamento attento alla situazione. Occorre distinguere Confucio storico, memoria dei discepoli e canonizzazione successiva. La tradizione non è uniforme: Mengzi e Xunzi elaborano concezioni differenti della natura umana e del ruolo educativo dei riti."], tags:["Cina","confucianesimo","virtù","riti","politica"], related:[{label:"Laozi",slug:"laozi",relation:"tradizioni cinesi in dialogo e confronto"}], bibliography:[{label:"Confucio, Analects: With Selections from Traditional Commentaries, trad. e cura di Edward Slingerland, Hackett, 2003.",type:"Testo primario / traduzione",note:"Traduzione annotata con selezioni di commentari tradizionali, glossario e bibliografia ragionata; utile per leggere i passi nel contesto della storia esegetica. Edizione italiana: Confucio, Dialoghi, traduzione e cura di Tiziana Lippiello, Einaudi, 2006, con testo cinese a fronte."}], keyTerms: [{"term":"ren (仁)","explanation":"Benevolenza o umanità, virtù relazionale centrale."},{"term":"li (禮)","explanation":"Riti e forme appropriate che educano le relazioni."},{"term":"yi (義)","explanation":"Rettitudine: ciò che è appropriato sul piano morale."},{"term":"junzi (君子)","explanation":"Persona esemplare formata attraverso studio e pratica."},{"term":"xiao (孝)","explanation":"Rispetto e cura filiale in un'etica relazionale."}], works: [{"title":"Dialoghi (Lunyu)","note":"Raccolta stratificata, non trascrizione immediata e unitaria."},{"title":"Mengzi","note":"Testo successivo che sviluppa la riflessione confuciana sulla natura umana."},{"title":"Xunzi","note":"Opera successiva che attribuisce un ruolo formativo decisivo a riti ed educazione."}], timeline: [{"date":"551 a.C.","event":"Data tradizionale della nascita."},{"date":"VI–V secolo a.C.","event":"Attività di maestro e consigliere, ricostruita da fonti posteriori."},{"date":"479 a.C.","event":"Data tradizionale della morte."},{"date":"V–III secolo a.C.","event":"Formazione e stratificazione dei materiali dei Lunyu."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"laozi", id:"AUT-000014", kind:"autore", title:"Laozi", subtitle:"Il Daodejing e le interpretazioni del dao", area:"Cina", period:"Antichità · datazione e storicità discusse", summary:"Figura tradizionalmente associata al Daodejing; la sua collocazione storica e il rapporto tra autore, testo e tradizione restano discussi.", sections:[
    {heading:"Profilo storico",paragraphs:["Laozi è una figura fondativa della tradizione daoista, ma le notizie biografiche tramandate dalle fonti antiche non consentono una ricostruzione storica sicura. Il Daodejing è un testo stratificato, la cui formazione è oggetto di dibattito.","È importante distinguere la figura tradizionale di Laozi, la storia del testo e le successive istituzioni daoiste."]},
    {heading:"Temi e problemi",paragraphs:["Il Daodejing riflette sul dao, sul de, sulla trasformazione, sulla spontaneità e sul wuwei, spesso tradotto come non-agire o agire senza forzatura. Le formule del testo sono dense e le traduzioni possono produrre interpretazioni differenti.","Il lessico va letto nel contesto della Cina antica, senza sovrapporvi categorie moderne in modo automatico."]},
    {heading:"Ricezione e confronti",paragraphs:["Il testo ha conosciuto commentari e interpretazioni molteplici. Le relazioni tra daoismo, confucianesimo e altre correnti cinesi vanno ricostruite storicamente, non desunte da somiglianze terminologiche."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Il Daodejing accosta immagini, paradossi, consigli politici e riflessioni sul linguaggio: non è un trattato sistematico. Il dao è detto e insieme sottratto alle denominazioni; il de indica la potenza attraverso cui si manifesta. Wuwei non significa inerzia, ma agire senza forzatura e senza moltiplicare il controllo. Il confronto tra testo ricevuto, manoscritti di Guodian e Mawangdui e commentario di Wang Bi mostra quanto la storia testuale condizioni l’interpretazione."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["La lettura del Daodejing deve tenere conto della pluralità dei testimoni: i manoscritti di Guodian non contengono l'intero testo ricevuto e quelli di Mawangdui presentano differenze d'ordine e varianti. Questi dati non autorizzano a ricostruire una versione originaria certa, ma consentono di osservare la circolazione e la riorganizzazione del materiale testuale.","Il rapporto tra Laozi e daoismo religioso va trattato storicamente. Il testo è diventato scrittura canonica in tradizioni religiose sviluppatesi nel tempo, ma non coincide con l'intero daoismo, che comprende rituali, istituzioni, pratiche di longevità e cosmologie. Distinguere daoismo filosofico e religioso può essere utile come prima mappa, purché non si trasformi in una separazione assoluta."]}], thoughtAnalysis:["Il Daodejing mette in discussione la pretesa di produrre ordine attraverso controllo e intervento incessante. Dao è la Via o il processo generativo, ma non può essere esaurito da una definizione: il linguaggio fissa e separa ciò che è dinamico e relazionale. De indica la potenza o efficacia attraverso cui la Via si manifesta. Le immagini dell’acqua, del vuoto e del legno non lavorato rovesciano le gerarchie comuni: ciò che appare debole può durare, ciò che non impone può risultare efficace. Il testo usa paradossi e immagini, non un sistema scolastico di definizioni.","Wuwei non significa inerzia, ma agire senza forzatura, accordandosi ai processi invece di moltiplicare ostacoli e desideri imposti. In politica suggerisce di evitare il sovraccarico di norme e ambizioni, senza per questo costituire un programma moderno univoco. La figura storica di Laozi è incerta e il testo è stratificato: Guodian e Mawangdui attestano forme differenti. La successiva tradizione daoista religiosa amplia il classico in direzioni molteplici. Bisogna quindi distinguere autore tradizionale, formazione del testo e storia delle pratiche daoiste."], tags:["Cina","daoismo","dao","wuwei"], related:[{label:"Confucio",slug:"confucio",relation:"tradizioni cinesi in dialogo e confronto"}], bibliography:[{label:"Laozi, The Daodejing of Laozi, trad. e cura di Philip J. Ivanhoe, Hackett, 2002.",type:"Testo primario / traduzione",note:"Traduzione filosofica introdotta e annotata. Da affiancare al confronto tra testimoni manoscritti, in particolare i manoscritti di Mawangdui, e alle tradizioni dei commentari."}], keyTerms: [{"term":"dao (道)","explanation":"Via o processo fondamentale, non riducibile a un oggetto definito."},{"term":"de (德)","explanation":"Potenza o efficacia attraverso cui si manifesta il dao."},{"term":"wuwei (無為)","explanation":"Agire senza forzatura e senza intervento artificioso."},{"term":"ziran (自然)","explanation":"Spontaneità o ciò-che-è-così-da-sé."},{"term":"pu (樸)","explanation":"Semplicità non intagliata, immagine della non-artificialità."}], works: [{"title":"Daodejing","note":"Testo composito tradizionalmente attribuito a Laozi; datazione discussa."},{"title":"Manoscritti di Guodian","note":"Testimoni su bambù con materiali paralleli al testo ricevuto."},{"title":"Manoscritti di Mawangdui","note":"Testimoni su seta con varianti e ordine differente."}], timeline: [{"date":"IV–III secolo a.C.","event":"Testimoni di Guodian; non attestano una biografia certa di Laozi."},{"date":"II secolo a.C.","event":"Deposizione dei manoscritti di Mawangdui."},{"date":"II secolo d.C.","event":"Crescita di movimenti e istituzioni daoiste."},{"date":"III secolo d.C.","event":"Commentario di Wang Bi, decisivo per la ricezione del testo."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"nagarjuna", id:"AUT-000015", kind:"autore", title:"Nāgārjuna", subtitle:"La via di mezzo, la vacuità e l'origine dipendente", area:"India", period:"Antichità tarda · cronologia discussa", summary:"Filosofo buddhista associato alla formazione della scuola Madhyamaka e a un'analisi critica delle concezioni sostanzialiste.", sections:[
    {heading:"Profilo storico",paragraphs:["Le informazioni biografiche su Nāgārjuna sono incerte e provengono da tradizioni differenti. La sua attività viene generalmente collocata nei primi secoli dell'era comune, ma la cronologia precisa e l'attribuzione di alcune opere restano discusse.","Occorre distinguere il nucleo delle opere considerate più plausibilmente autentiche dalla letteratura successiva attribuita al suo nome."]},
    {heading:"Temi e problemi",paragraphs:["La riflessione Madhyamaka analizza criticamente il sorgere dipendente e la vacuità (śūnyatā), contestando che i fenomeni possiedano un'esistenza intrinseca e indipendente. La critica non equivale a sostenere semplicemente che nulla esista.","Le argomentazioni si collocano nel dibattito buddhista indiano: il loro significato si perde se isolate dal contesto dottrinale."]},
    {heading:"Ricezione e confronti",paragraphs:["Le opere attribuite a Nāgārjuna hanno avuto una vasta ricezione in India e in Asia orientale, in particolare nelle tradizioni buddhiste tibetane e cinesi. Le scuole successive hanno sviluppato interpretazioni differenti."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["L’analisi non nega l’esistenza convenzionale dei fenomeni, ma contesta che possiedano svabhāva, una natura indipendente da cause e relazioni. Nāgārjuna applica argomenti a causalità, movimento, tempo e identità personale. Il nesso tra origine dipendente, vacuità e designazione convenzionale evita la lettura nichilistica: le due verità non sono due mondi separati. Le opere attribuite a Nāgārjuna non hanno tutte la stessa certezza attributiva."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["La Mūlamadhyamakakārikā è organizzata in capitoli che sottopongono a esame categorie centrali: causalità, movimento, aggregati, elementi, desiderio, agente e azione, tempo e nirvāṇa. Il metodo non consiste nel proporre una teoria alternativa per ogni tema, ma nel mostrare le difficoltà delle posizioni che attribuiscono natura intrinseca ai fenomeni. La lettura dei singoli argomenti è più affidabile di una definizione isolata di vacuità.","Il rapporto tra Madhyamaka e altre scuole buddhiste va ricostruito attraverso controversie precise, per esempio con le teorie dell'Abhidharma e con le successive interpretazioni della coscienza. Non si deve assimilare automaticamente la vacuità alla nozione moderna di relatività o a una tesi secondo cui tutto sarebbe illusorio: sono analogie suggestive ma storicamente e filosoficamente limitate."]}], thoughtAnalysis:["Nāgārjuna critica l’idea che le cose possiedano una natura propria (svabhāva), indipendente da cause, condizioni, parti e relazioni. Le Stanze fondamentali mostrano che, analizzando causalità, movimento, identità e tempo, l’ipotesi di un’esistenza intrinseca genera contraddizioni. Vacuità non significa nulla assoluto: significa assenza di autonomia ontologica. I fenomeni esistono convenzionalmente proprio perché dipendono da condizioni. Vacuità e origine dipendente sono così due formulazioni connesse, che evitano sia l’eternalismo sia il nichilismo.","Le due verità distinguono il piano convenzionale, nel quale linguaggio e causalità funzionano, dalla comprensione ultima della dipendenza; non sono due mondi separati. Il metodo argomentativo mostra spesso le conseguenze problematiche delle tesi avversarie senza introdurre una nuova metafisica. Le interpretazioni successive, indiane e tibetane, non vanno attribuite automaticamente a Nāgārjuna. La critica della reificazione ha anche una finalità etica e soteriologica: riduce attaccamento e fissazione concettuale."], tags:["India","buddhismo","Madhyamaka","vacuità"], related:[], bibliography:[{label:"Nāgārjuna, The Fundamental Wisdom of the Middle Way: Nāgārjuna’s Mūlamadhyamakakārikā, trad. e commento di Jay L. Garfield, Oxford University Press, 1995.",type:"Testo primario / traduzione",note:"Traduzione filosofica con commento. Edizione italiana: Nāgārjuna, Madhyamaka kārikā; Vigraha vyāvartanī; Catuḥstava, introduzione, traduzione e note di Raniero Gnoli, Boringhieri, 1961 (comprende Le stanze del cammino di mezzo e altri testi). Un’altra edizione inglese di riferimento è Mark Siderits e Shōryū Katsura, Nāgārjuna’s Middle Way: Mūlamadhyamakakārikā, Wisdom Publications, 2013."}], keyTerms: [{"term":"śūnyatā","explanation":"Vacuità: assenza di esistenza intrinseca e indipendente."},{"term":"pratītyasamutpāda","explanation":"Origine dipendente: i fenomeni sorgono in dipendenza da condizioni."},{"term":"svabhāva","explanation":"Natura propria indipendente, sottoposta a critica."},{"term":"madhyamā pratipad","explanation":"Via di mezzo che evita posizioni estreme."},{"term":"dve satye","explanation":"Due verità, convenzionale e ultima, da non separare in due mondi."}], works: [{"title":"Mūlamadhyamakakārikā","note":"Opera fondamentale attribuita a Nāgārjuna."},{"title":"Vigrahavyāvartanī","note":"Testo polemico sulla possibilità e lo statuto della confutazione."},{"title":"Yuktiṣaṣṭikā","note":"Sessanta stanze sul ragionamento, con dettagli attributivi discussi."}], timeline: [{"date":"I–III secolo d.C.","event":"Fascia cronologica ampia proposta per Nāgārjuna."},{"date":"II–III secolo d.C.","event":"Collocazione spesso adottata per le opere principali."},{"date":"V–VI secolo d.C.","event":"Sviluppo di commentari madhyamaka in India."},{"date":"VII secolo d.C.","event":"Attività di Candrakīrti e successive linee esegetiche."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"avicenna", id:"AUT-000016", kind:"autore", title:"Avicenna (Ibn Sīnā)", subtitle:"Essenza, esistenza e filosofia della natura", area:"Mondo persiano e islamico", period:"X–XI secolo", summary:"Filosofo, medico e scienziato (circa 980–1037), autore di opere influenti in logica, metafisica, psicologia e medicina.", sections:[
    {heading:"Profilo storico",paragraphs:["Ibn Sīnā, noto in latino come Avicenna, nacque nell'Asia centrale e operò in diversi centri del mondo persiano e islamico. La sua produzione comprende opere enciclopediche, trattati e testi di diversa destinazione.","La sua attività si colloca in un ambiente intellettuale segnato dalla traduzione e dall'elaborazione della filosofia greca, dalla teologia islamica e dalle scienze del tempo."]},
    {heading:"Temi e problemi",paragraphs:["Nella metafisica avicenniana è centrale la distinzione tra essenza ed esistenza e l'analisi dell'essere necessario e degli esseri possibili. La sua psicologia comprende argomenti sull'anima e sulla conoscenza.","Queste dottrine si sviluppano in un sistema articolato e non possono essere comprese come semplice ripetizione di Aristotele o come anticipazione diretta della filosofia moderna."]},
    {heading:"Ricezione e confronti",paragraphs:["Le opere di Avicenna furono lette e discusse in molteplici tradizioni islamiche e, attraverso traduzioni latine ed ebraiche, ebbero un ruolo rilevante anche nelle filosofie medievali europee. Le ricezioni furono selettive e spesso critiche."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Per Avicenna l’essenza considerata in se stessa non implica né esistenza né non-esistenza; gli esseri possibili richiedono una causa. L’analisi conduce alla distinzione tra necessario per sé e possibile per sé. L’argomento dell’uomo volante riguarda l’autocoscienza: anche senza percezioni corporee il soggetto affermerebbe la propria esistenza. Va letto nel contesto della psicologia e distinto dalle successive interpretazioni latine, che selezionarono alcuni nuclei del suo pensiero."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["La metafisica di Avicenna non si limita alla distinzione tra essenza ed esistenza. Esamina la causalità, l'unità del necessario, l'intelletto e la struttura dell'essere; il necessario per sé non appartiene a una classe di enti accanto agli altri, ma svolge una funzione esplicativa nell'ordine causale. È importante leggere queste tesi nella sequenza dell'opera, evitando di isolare formule diventate celebri nella ricezione scolastica.","La psicologia avicenniana collega anima, percezione, immaginazione e intelletto. L'esperimento mentale dell'uomo volante è un argomento sull'autocoscienza, non una dimostrazione completa dell'intero sistema dualistico in senso moderno. Il confronto con al-Ghazālī, Averroè e la scolastica latina permette di distinguere la formulazione originaria dalle obiezioni e dalle trasformazioni successive."]}], thoughtAnalysis:["Avicenna rielabora Aristotele integrando logica, scienze naturali, psicologia e metafisica. La distinzione fra essenza ed esistenza è centrale: sapere che cosa una cosa è non dimostra che essa esista. Gli enti contingenti richiedono una causa; l’analisi conduce al necessario per sé, che non riceve l’essere da altro. La metafisica diventa così indagine sull’essere e sulle sue cause ultime. Non si tratta di ripetere la teologia tradizionale, ma di argomentare a partire dalla struttura modale del reale.","L’esperimento mentale dell’uomo volante indaga la consapevolezza immediata di sé anche in assenza di percezioni corporee: distingue autocoscienza e conoscenza sensibile, senza provare che si possa vivere senza corpo. La teoria dell’intelletto descrive il passaggio dalla potenzialità alla conoscenza. La medicina mostra l’intreccio fra osservazione e spiegazione causale. Avicenna trasformò profondamente l’eredità aristotelica e influenzò filosofie islamiche, ebraiche e latine."], tags:["Persia","filosofia islamica","metafisica","medicina"], related:[{label:"Aristotele",slug:"aristotele",relation:"rielaborazione critica di temi aristotelici"}], bibliography:[{label:"Avicenna, The Metaphysics of The Healing, trad. e commento di Michael E. Marmura, Brigham Young University Press, 2005.",type:"Studio secondario",note:"Traduzione della sezione metafisica dell’enciclopedia al-Shifāʾ. Per un inquadramento complessivo del pensiero e del contesto storico: Jon McGinnis, Avicenna, Oxford University Press, 2010."}], keyTerms: [{"term":"wājib al-wujūd","explanation":"Necessario per sé: ciò la cui esistenza non dipende da altro."},{"term":"māhiyya","explanation":"Quiddità o che-cos'è, distinguibile concettualmente dall'esistenza."},{"term":"wujūd","explanation":"Esistenza, tema centrale della metafisica avicenniana."},{"term":"nafs","explanation":"Anima, principio della vita e oggetto di analisi psicologica."},{"term":"burhān","explanation":"Dimostrazione scientifica, con premesse e nessi necessari."}], works: [{"title":"Kitāb al-Šifāʾ","note":"Enciclopedia filosofica di logica, fisica, matematica e metafisica."},{"title":"al-Qānūn fī al-ṭibb","note":"Canone della medicina, influente nelle tradizioni arabe e latine."},{"title":"al-Išārāt wa-l-tanbīhāt","note":"Opera matura e sintetica, accompagnata da importanti commentari."},{"title":"Dānešnāme-ye ʿAlāʾī","note":"Compendio filosofico in persiano."}], timeline: [{"date":"980","event":"Nascita presso Bukhara, secondo la data tradizionale."},{"date":"fine X secolo","event":"Formazione in logica, medicina e scienze."},{"date":"inizio XI secolo","event":"Attività presso diverse corti dell'Iran."},{"date":"1025 circa","event":"Completamento convenzionalmente datato del Canone della medicina."},{"date":"1037","event":"Morte ad Hamadan."}], editorialStatus:"edizione editoriale 1.0" }
,
  { slug:"dao", id:"CON-000001", kind:"concetto", title:"Dao (道)", subtitle:"Via, corso e principio nel pensiero cinese", area:"Cina", period:"Cina antica · testi e scuole di epoche diverse", summary:"Dao è un termine centrale in diverse tradizioni cinesi, traducibile secondo i contesti come via, percorso, metodo o corso. Non possiede un significato unico e immutabile.", sections:[
    {heading:"Significati e contesti",paragraphs:["Nel Daodejing il dao è descritto con un linguaggio spesso paradossale: non è facilmente riducibile a un oggetto o a una definizione. In altri testi e scuole cinesi, il termine può indicare una via di condotta, un metodo, un ordine o un corso delle cose.","Tradurre sempre dao con 'principio' rischia di irrigidire un termine il cui significato dipende dall'opera, dal periodo e dalla questione affrontata."]},
    {heading:"Problemi filosofici",paragraphs:["Il concetto invita a interrogare il rapporto tra linguaggio e realtà, tra spontaneità e azione, tra ordine cosmico e condotta umana. Nel daoismo classico il wuwei è spesso associato a un agire non forzato; non equivale semplicemente all'inattività.","Il dao compare anche in contesti non daoisti: la sua presenza lessicale non basta quindi a identificare una scuola o una dottrina."]},
    {heading:"Confronti e cautele",paragraphs:["Accostare dao a concetti come logos, natura o via può essere utile come domanda comparativa, ma non stabilisce equivalenze. Per sostenere un rapporto storico servono prove di contatto, traduzione o ricezione."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Nei Dialoghi confuciani dao può indicare la via dell’apprendimento e del governo; nel Daodejing assume portata cosmologica; nello Zhuangzi viene interrogato attraverso prospettive e trasformazioni. Questi usi non costituiscono una dottrina unica. Via, corso, metodo e norma rendono aspetti differenti del termine. Il confronto con logos o dharma è utile solo se si precisa la domanda comparativa e non si cercano equivalenti universali."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["La comparazione tra i diversi usi di dao dovrebbe partire da passi paralleli, non da definizioni astratte. Nei testi confuciani la via può essere una pratica morale e politica trasmissibile; nel Daodejing il linguaggio paradossale mette in questione la pretesa di fissare la via in una norma; nello Zhuangzi il problema si intreccia con la relatività delle prospettive e con la trasformazione delle cose.","Una ricerca lessicale dovrebbe distinguere dao come nome comune di percorso o metodo, gli usi normativi e le elaborazioni cosmologiche. Anche la grafia e la traduzione variano nelle diverse epoche. Per questo la voce non dovrebbe presentare “la dottrina del dao”, ma una rete di occorrenze, testi, pratiche e controversie."]}], thoughtAnalysis:["Dao significa via o modo di procedere, ma nelle tradizioni cinesi assume funzioni diverse: processo cosmico, orientamento morale, metodo o pratica corretta. Nel Daodejing è il principio dinamico che non si lascia fissare in un nome; in testi confuciani può indicare la via della formazione e del governo. Non è sempre una sostanza o una divinità creatrice. La traduzione va contestualizzata e non deve sovrapporre automaticamente categorie metafisiche europee.","Il confronto fra daoismo e confucianesimo mostra differenti concezioni dell’ordine: il primo critica la forzatura e l’intervento eccessivo, il secondo valorizza studio, ritualità e coltivazione delle relazioni. Le differenze non formano però due blocchi sempre contrapposti. Per comprendere il termine occorre precisare autore, testo, periodo e funzione; la sua storia include sviluppi religiosi, politici e commentariali."], tags:["Cina","daoismo","Daodejing","wuwei","linguaggio"], related:[{label:"Laozi",slug:"laozi",relation:"testo tradizionalmente associato al concetto"},{label:"Confucio",slug:"confucio",relation:"altro contesto classico di uso del termine dao"}], bibliography:[{label:"Laozi, The Daodejing of Laozi, trad. e cura di Philip J. Ivanhoe, Hackett, 2002.",type:"Studio secondario",note:"Utile per l’analisi del lessico del dao nel testo. Per un’interpretazione filosofica più ampia del pensiero cinese: Chad Hansen, A Daoist Theory of Chinese Thought: A Philosophical Interpretation, Oxford University Press, 1992."},{label:"Laozi, Lao-Tzu, Te-Tao Ching: A New Translation Based on the Recently Discovered Ma-wang-tui Texts, trad. Robert G. Henricks, Ballantine Books, 1989.",type:"Testo primario / traduzione",note:"Traduzione fondata sui manoscritti su seta di Mawangdui, da confrontare con il testo ricevuto e con il commentario di Wang Bi; non rappresenta una versione unica o definitiva del Daodejing."},{label:"Jingmenshi bowuguan (a cura di), Guodian Chu mu zhujian, Wenwu chubanshe, 1998.",type:"Edizione critica / testimone",note:"Pubblicazione dei manoscritti su listarelle di bambù della tomba di Guodian. Testimonianza antica parziale del Laozi, con ordine e varianti che non coincidono con il testo canonico ricevuto."}], keyTerms: [{"term":"dao (道)","explanation":"Via, corso o principio di processualità; significato variabile secondo i testi."},{"term":"de (德)","explanation":"Efficacia o potenza propria di una configurazione del dao."},{"term":"wuwei (無為)","explanation":"Non-forzatura: modalità di azione non coercitiva."},{"term":"ziran (自然)","explanation":"Spontaneità, ciò che avviene secondo il proprio corso."},{"term":"ming (名)","explanation":"Nome o denominazione; problema del linguaggio e della classificazione."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"logos", id:"CON-000002", kind:"concetto", title:"Logos (λόγος)", subtitle:"Discorso, ragione, spiegazione e ordine", area:"Grecia antica", period:"Dalla filosofia arcaica all'età ellenistica e oltre", summary:"Logos è un termine greco polisemico che può significare parola, discorso, argomentazione, ragione o spiegazione; i suoi usi cambiano profondamente nel tempo.", sections:[
    {heading:"Significati e contesti",paragraphs:["Nella lingua greca logos designa forme diverse del dire e del rendere ragione. Nei frammenti attribuiti a Eraclito assume un ruolo filosofico discusso; in Platone e Aristotele ricorre in molteplici contesti logici, dialettici ed esplicativi.","Nello stoicismo il logos è connesso anche alla razionalità che struttura il cosmo. In autori e ambienti successivi il termine viene rielaborato in modi non sovrapponibili."]},
    {heading:"Problemi filosofici",paragraphs:["Il termine pone questioni sul rapporto tra linguaggio e pensiero, tra argomentazione e conoscenza, e tra razionalità umana e ordine del mondo. La traduzione deve seguire il contesto: 'parola', 'ragione' e 'discorso' non sono intercambiabili in ogni passo.","La storia del concetto non è una linea dottrinale continua: occorre ricostruire i singoli usi e le trasformazioni semantiche."]},
    {heading:"Confronti e cautele",paragraphs:["Il confronto con dao, dharma o altri termini può mettere a fuoco diverse concezioni di ordine e intelligibilità, ma non autorizza a trattarli come sinonimi né a postulare influenze senza documentazione."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Logos può significare discorso, resoconto, spiegazione, argomento, ragione o proporzione. In Eraclito è legato a un ordine comune, ma i frammenti sono trasmessi da autori posteriori. Lo stoicismo sviluppa poi una concezione cosmologica del logos come principio razionale immanente. Non bisogna retroproiettare questo uso su ogni occorrenza precedente né confonderlo con il Logos cristiano senza ricostruire le mediazioni storiche."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["Nel pensiero greco il significato di logos dipende anche dalla costruzione grammaticale e dal genere del testo: un logos può essere un discorso, una spiegazione, un argomento o un rapporto. Nei frammenti presocratici la ricostruzione è resa più difficile dal fatto che spesso leggiamo citazioni inserite in opere molto posteriori. È necessario distinguere il testo citato dal contesto dell'autore che lo trasmette.","Per la storia successiva occorre seguire almeno tre passaggi senza confonderli: l'uso filosofico greco, la rielaborazione stoica del logos cosmico e le tradizioni giudaico-ellenistiche e cristiane. Le somiglianze terminologiche non provano una derivazione lineare. Una comparazione solida ricostruisce mediazioni, traduzioni e specifiche funzioni teologiche o filosofiche."]}], thoughtAnalysis:["Logos può significare parola, discorso, ragione, spiegazione o principio intelligibile. Non esiste una dottrina uniforme: in Eraclito è associato a un ordine comune, in Platone alla ricerca razionale, in Aristotele alla capacità di argomentare; gli stoici lo pensano come principio razionale attivo del cosmo. Ogni uso va ricondotto al testo e alla teoria che lo sostiene.","La traduzione con ragione o parola illumina aspetti diversi e può essere riduttiva. Nel pensiero stoico il logos cosmico sostiene una visione razionale e provvidenziale della natura, mentre nell’essere umano si manifesta nella capacità di giudizio. Il termine ha poi una storia decisiva nella filosofia tardo-antica e cristiana. Non va equiparato al dao per semplice analogia lessicale: occorre confrontare funzioni e contesti."], tags:["Grecia","linguaggio","ragione","stoicismo","metafisica"], related:[{label:"Platone",slug:"platone",relation:"usi dialogici e argomentativi del termine"},{label:"Aristotele",slug:"aristotele",relation:"analisi del discorso e della spiegazione"}], bibliography:[{label:"André Laks e Glenn W. Most (a cura di), Early Greek Philosophy, Loeb Classical Library, Harvard University Press, 2016.",type:"Edizione critica / testimone",note:"Edizione con testo greco, traduzione e apparati per i presocratici, utile per contestualizzare i frammenti di Eraclito."},{label:"G. S. Kirk, J. E. Raven e M. Schofield, The Presocratic Philosophers, 2ª ed., Cambridge University Press, 1983.",type:"Studio secondario",note:"Studio storico e filosofico dei presocratici; da usare insieme alle edizioni dei frammenti e non come sostituto delle fonti."},{label:"Hermann Diels e Walther Kranz (a cura di), Die Fragmente der Vorsokratiker, 6ª ed., Weidmann, 1951–1952.",type:"Edizione critica / testimone",note:"Raccolta di frammenti e testimonianze; per Eraclito occorre distinguere citazioni, parafrasi e testimonianze indirette, senza trattare il logos come un concetto già univoco."},{label:"André Laks e Glenn W. Most (a cura di), Early Greek Philosophy, vol. III, Harvard University Press, 2016.",type:"Edizione critica / testimone",note:"Edizione critica con testo, traduzione e testimonianze; utile per confrontare la numerazione e la selezione dei frammenti con Diels–Kranz."}], keyTerms: [{"term":"logos","explanation":"Parola, discorso, ragione o struttura intelligibile; non ha un equivalente unico."},{"term":"physis","explanation":"Natura o processo di emergenza, importante nel pensiero greco."},{"term":"kosmos","explanation":"Ordine o assetto del mondo, con significati variabili."},{"term":"ratio","explanation":"Termine latino che traduce alcuni usi di logos senza esaurirli."},{"term":"verbum","explanation":"Resa latina di logos in contesti teologici specifici."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"dharma", id:"CON-000003", kind:"concetto", title:"Dharma (धर्म)", subtitle:"Norma, insegnamento, dovere e ordine", area:"India", period:"Tradizioni indiane antiche e sviluppi successivi", summary:"Dharma è un termine dalle molteplici accezioni nelle tradizioni indiane: può indicare norma, dovere, insegnamento, qualità o realtà, secondo il contesto testuale e religioso-filosofico.", sections:[
    {heading:"Significati e contesti",paragraphs:["Nelle tradizioni brahmaniche il termine può riferirsi a norme, doveri e ordine sociale o rituale. Nel buddhismo, dharma può indicare l'insegnamento del Buddha e, in contesti filosofici specifici, elementi o fenomeni dell'esperienza.","Non esiste una singola definizione valida per tutti i testi e le scuole. Le traduzioni 'legge', 'religione' o 'dovere' sono parziali e vanno motivate caso per caso."]},
    {heading:"Problemi filosofici",paragraphs:["Il concetto si intreccia con questioni di normatività, conoscenza, pratica, liberazione e costituzione della realtà. La sua funzione cambia tra testi rituali, epici, trattati normativi e scuole buddhiste.","È essenziale distinguere gli usi prescrittivi dagli usi descrittivi o ontologici, evitando di appiattirli in una sola categoria."]},
    {heading:"Confronti e cautele",paragraphs:["Un confronto con nomos, legge o ordine può essere utile, ma non produce equivalenza. Le istituzioni e le cosmologie entro cui dharma opera sono storicamente specifiche."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Nei testi vedici e brahmanici dharma si collega a ordine, norma e dovere; nei testi buddhisti pāli, dhamma può indicare l’insegnamento del Buddha o i fenomeni; nel giainismo assume anche significati cosmologici tecnici. Il termine può riferirsi a posizione sociale, fase della vita o insegnamento liberatorio. Per tradurre un passo occorre identificare lingua, genere e tradizione: non esiste una definizione unica valida per tutti i contesti indiani."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["Il termine è inseparabile dai generi testuali. Nei testi normativi brahmanici può organizzare doveri e status; nei discorsi buddhisti il dhamma può designare insegnamento, verità o fenomeni; nei testi jaina assume un lessico tecnico proprio. Tradurre ogni occorrenza con “legge” o “religione” oscura differenze decisive e può importare categorie europee non pertinenti.","Il confronto tra dharma e concetti come legge, ordine cosmico o dovere va condotto su testi e situazioni determinate. Anche all'interno di una tradizione le prescrizioni possono essere contestate, reinterpretate o adattate. La voce dovrebbe rinviare a sottocontesti distinti e segnalare quando una traduzione è una scelta interpretativa piuttosto che un equivalente lessicale."]}], thoughtAnalysis:["Dharma è un termine polisemico: può significare norma, dovere, ordine, insegnamento, qualità o fenomeno. Nelle tradizioni brahmaniche è legato anche a ordine rituale e sociale; nel buddhismo indica l’insegnamento del Buddha o fattori dell’esperienza; nel jainismo assume ulteriori significati tecnici. Non è traducibile sempre con religione, legge o moralità. La sua interpretazione richiede di specificare lingua, epoca, genere testuale e tradizione.","Il concetto interroga il rapporto fra ordine del mondo, norma e condotta. Le fonti mostrano spesso conflitti fra doveri e circostanze, che impediscono di ridurre il dharma a un codice meccanico. Nel buddhismo il Dharma orienta alla cessazione della sofferenza, mentre i dharma come elementi dell’esperienza appartengono a elaborazioni analitiche. I confronti con virtù e legge sono utili solo mantenendo le differenze."], tags:["India","sanscrito","buddhismo","normatività","tradizioni indiane"], related:[{label:"Nāgārjuna",slug:"nagarjuna",relation:"dibattiti buddhisti sulla natura dei fenomeni" }], bibliography:[{label:"Patrick Olivelle, The Early Upaniṣads: Annotated Text and Translation, Oxford University Press, 1998.",type:"Studio secondario",note:"Edizione e traduzione annotata utile per i contesti vedici e upaniṣadici, senza ridurre a essa tutti gli usi storici di dharma."},{label:"Rupert Gethin, The Foundations of Buddhism, Oxford University Press, 1998.",type:"Studio secondario",note:"Introduzione storico-dottrinale per gli usi buddhisti di dharma; i significati tecnici vanno verificati nei singoli testi e nelle rispettive scuole."},{label:"Patrick Olivelle (a cura di), Manu’s Code of Law: A Critical Edition and Translation of the Mānava-Dharmaśāstra, Oxford University Press, 2005.",type:"Edizione critica / testimone",note:"Edizione critica e traduzione di una fonte normativa sanscrita. Documenta uno specifico uso brahmanico e giuridico di dharma, non l'intero campo semantico indiano."},{label:"O. von Hinüber e K. R. Norman (a cura di), Dhammapada, 2ª ed., Pali Text Society, 2014.",type:"Testo primario / traduzione",note:"Edizione del testo pāli basata sulla ricerca filologica; utile per il contesto buddhista, da non confondere con gli usi brahmanici o normativi di dharma."}], keyTerms: [{"term":"dharma","explanation":"Termine polisemico: norma, insegnamento, dovere, qualità o fenomeno secondo il contesto."},{"term":"dhamma","explanation":"Forma pāli, centrale nei testi buddhisti antichi."},{"term":"svadharma","explanation":"Dovere o norma propria, con rilievo in testi hindu."},{"term":"dharmakāya","explanation":"Corpo del Dharma nella dottrina mahāyāna."},{"term":"sanātana dharma","explanation":"Espressione con storie d'uso differenti, non sinonimo universale di hinduismo."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"sunyata", id:"CON-000004", kind:"concetto", title:"Śūnyatā (vacuità)", subtitle:"Assenza di esistenza intrinseca nel pensiero buddhista", area:"India", period:"Buddhismo mahāyāna · primi secoli dell'era comune e sviluppi", summary:"Nel Madhyamaka la vacuità indica che i fenomeni non esistono in modo autonomo e intrinseco, ma sorgono in dipendenza da condizioni e relazioni.", sections:[
    {heading:"Significati e contesti",paragraphs:["Śūnyatā è un termine centrale in diverse correnti mahāyāna, con elaborazioni particolarmente influenti nel Madhyamaka. La sua interpretazione richiede attenzione ai testi, agli argomenti e alle controversie tra scuole.","La vacuità non significa semplicemente che le cose non esistano: riguarda il modo in cui esistono, ossia senza natura propria indipendente."]},
    {heading:"Problemi filosofici",paragraphs:["Il concetto è legato all'origine dipendente e alla critica delle posizioni che attribuiscono ai fenomeni un'essenza autonoma. Nelle argomentazioni madhyamaka la vacuità stessa non deve essere trasformata in una nuova sostanza o fondamento assoluto.","La relazione tra verità convenzionale e verità ultima è decisiva per comprendere la funzione del concetto."]},
    {heading:"Confronti e cautele",paragraphs:["Tradurre śūnyatā con 'nulla' o assimilarla a forme occidentali di nichilismo è fuorviante. I confronti con il concetto di essere o con teorie della sostanza devono partire dai testi e dalle differenze di problema."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Śūnyatā non indica un vuoto assoluto, ma l’assenza di esistenza intrinseca: i fenomeni sorgono in dipendenza da cause, parti, relazioni e designazioni. La vacuità non annulla il mondo convenzionale e non è una sostanza nascosta. Va interpretata insieme alle due verità e all’origine dipendente; se diventa una tesi assoluta, si trasforma proprio in ciò che intende criticare. Le scuole madhyamaka hanno sviluppato letture non uniformi."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["La vacuità si chiarisce attraverso l'analisi della dipendenza: ciò che sorge da condizioni non possiede un'essenza indipendente. La formula non va convertita in una teoria secondo cui le cose sarebbero soltanto parole; la designazione convenzionale ha un ruolo, ma non elimina causalità, esperienza e pratica. La tensione tra analisi ultima e funzionamento convenzionale è precisamente uno dei problemi centrali del Madhyamaka.","Il confronto con le scuole buddhiste richiede attenzione alle diverse interpretazioni delle due verità e al modo in cui i commentatori spiegano il rapporto tra ragionamento e liberazione. Le traduzioni moderne di śūnyatā come “vuoto”, “vacuità” o “emptiness” orientano diversamente il lettore: la scheda dovrebbe conservare il termine sanscrito e spiegare ogni scelta."]}], thoughtAnalysis:["Śūnyatā, vacuità, non significa che nulla esista, ma che i fenomeni non possiedono esistenza autonoma. Essi sorgono in dipendenza da cause, condizioni, parti e designazioni. La vacuità non è una sostanza nascosta né un nulla assoluto; anche essa non deve essere reificata come entità indipendente. La critica riguarda l’idea di un nucleo intrinseco che sussista da sé.","Vacuità e origine dipendente sono connesse: poiché le cose dipendono da condizioni, possono sorgere, mutare e cessare. Le due verità non dividono la realtà in due mondi, ma distinguono il funzionamento convenzionale dalla comprensione ultima della dipendenza. Questa analisi ha conseguenze etiche e soteriologiche perché riduce attaccamento e fissazione identitaria. Le scuole buddhiste ne hanno dato interpretazioni differenti."], tags:["India","buddhismo","Madhyamaka","origine dipendente","metafisica"], related:[{label:"Nāgārjuna",slug:"nagarjuna",relation:"autore centrale per la formulazione Madhyamaka"}], bibliography:[{label:"Nāgārjuna, The Fundamental Wisdom of the Middle Way, trad. e commento di Jay L. Garfield, Oxford University Press, 1995.",type:"Testo primario / traduzione",note:"Fonte primaria tradotta con commento filosofico per lo studio di śūnyatā e origine dipendente nel Madhyamaka."},{label:"Jan Westerhoff, Nāgārjuna’s Madhyamaka: A Philosophical Introduction, Oxford University Press, 2009.",type:"Studio secondario",note:"Introduzione specialistica alle argomentazioni e ai problemi filosofici della tradizione."}], keyTerms: [{"term":"śūnyatā","explanation":"Vacuità da esistenza intrinseca, non annullamento dei fenomeni."},{"term":"svabhāva","explanation":"Natura propria indipendente, negata dall'analisi madhyamaka."},{"term":"pratītyasamutpāda","explanation":"Origine dipendente, correlato esplicativo della vacuità."},{"term":"prajñā","explanation":"Sapienza o discernimento che comprende la vacuità."},{"term":"saṃvṛti-satya","explanation":"Verità convenzionale, ambito delle pratiche e designazioni condivise."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"essere", id:"CON-000005", kind:"concetto", title:"Essere", subtitle:"Che cosa significa che qualcosa è?", area:"Comparativo · molteplici tradizioni", period:"Problema trasversale, con lessici non equivalenti", summary:"'Essere' è una categoria di grande rilievo in diverse storie filosofiche, ma le parole e i problemi che vi vengono ricondotti non coincidono automaticamente tra lingue e tradizioni.", sections:[
    {heading:"Problema filosofico",paragraphs:["Nella filosofia greca il problema dell'essere assume forme diverse da Parmenide ad Aristotele. In Aristotele la domanda sull'essere si articola in molteplici sensi, con particolare attenzione alla sostanza.","Altre tradizioni hanno sviluppato analisi dell'esistenza, della realtà, del divenire e della dipendenza attraverso lessici e presupposti differenti. Non è corretto supporre che ogni lingua filosofica possieda un equivalente diretto del termine italiano 'essere'."]},
    {heading:"Distinzioni necessarie",paragraphs:["Occorre distinguere l'uso grammaticale del verbo essere, l'esistenza di qualcosa, l'identità, la predicazione e la questione metafisica dell'essere. Confondere questi piani produce apparenti problemi o false analogie.","Il confronto interculturale deve partire dai testi originali e dalle loro traduzioni, rendendo esplicite le scelte terminologiche."]},
    {heading:"Confronti e cautele",paragraphs:["Questo lemma è un nodo comparativo, non l'affermazione che tutte le tradizioni abbiano formulato la stessa ontologia. Le relazioni tra lessici vanno documentate e descritte senza imporre una griglia unica."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Parmenide, Platone e Aristotele pongono problemi differenti sotto il termine “essere”: la via di ciò che è, il rapporto tra essere e divenire, i significati molteplici dell’essere e la centralità della sostanza. Non si deve assumere che il verbo essere in greco, latino, sanscrito, cinese o arabo organizzi le stesse distinzioni. La voce è una mappa di problemi e rinvii, non una definizione metafisica universale."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["La voce comparativa deve distinguere almeno quattro problemi: esistenza, predicazione, identità e sostanza. Nei testi greci questi problemi possono intrecciarsi, ma non sono sinonimi. Parmenide, Platone e Aristotele offrono snodi diversi; il lessico latino medievale e le traduzioni moderne hanno poi riorganizzato la discussione in modi non sempre sovrapponibili all'originale.","Un confronto interculturale deve evitare di assumere che ogni lingua possieda un unico equivalente del verbo greco einai. Il cinese classico, il sanscrito e l'arabo filosofico articolano le questioni ontologiche attraverso risorse linguistiche e tradizioni differenti. Il confronto è più preciso se parte da problemi determinati, come identità nel mutamento o rapporto tra ciò che una cosa è e il fatto che esista."]}], thoughtAnalysis:["La filosofia ha interrogato l’essere chiedendo che cosa significhi che qualcosa è. Parmenide lega essere, pensiero e dicibilità; Platone nel Sofista distingue il non-essere assoluto dalla differenza; Aristotele analizza i molti sensi dell’essere e la priorità della sostanza. La storia successiva comprende prospettive teologiche, scolastiche, moderne e fenomenologiche: non esiste una definizione unica che le esaurisca.","Le domande sull’essere riguardano esistenza, identità, predicazione, possibilità e tempo. Dire che qualcosa è può significare che esiste, che possiede una proprietà o che una proposizione è vera. Il confronto con la vacuità buddhista può mettere alla prova l’idea di natura intrinseca, ma non autorizza a sovrapporre ontologia greca e Madhyamaka: problemi e finalità sono differenti."], tags:["metafisica","ontologia","Grecia","comparazione","linguaggio"], related:[{label:"Platone",slug:"platone",relation:"problemi delle forme e della realtà"},{label:"Aristotele",slug:"aristotele",relation:"analisi dei molteplici sensi dell'essere"}], bibliography:[{label:"André Laks e Glenn W. Most (a cura di), Early Greek Philosophy, Loeb Classical Library, Harvard University Press, 2016.",type:"Edizione critica / testimone",note:"Edizione e traduzione dei testi presocratici, utile per lo studio di Parmenide e delle diverse formulazioni del problema dell’essere."},{label:"Aristotele, The Complete Works of Aristotle: The Revised Oxford Translation, a cura di Jonathan Barnes, 2 voll., Princeton University Press, 1984.",type:"Edizione di riferimento",note:"Per la Metafisica, in particolare i libri Γ, Ζ e Η, sui molteplici sensi dell’essere e sulla sostanza."},{label:"A. H. Coxon, The Fragments of Parmenides: A Critical Text with Introduction, Translation, the Ancient Testimonia and a Commentary, edizione riveduta e ampliata, Parmenides Publishing, 2009.",type:"Edizione critica / testimone",note:"Edizione critica dei frammenti e delle testimonianze del poema; permette di verificare il lessico greco senza assumere che l'italiano 'essere' ne esaurisca i significati."},{label:"Immanuel Bekker (a cura di), Aristotelis Opera, 5 voll., Berlin, 1831.",type:"Edizione critica / testimone",note:"Edizione di riferimento per la paginazione Bekker del corpus aristotelico; per la questione dell'essere sono centrali soprattutto Metafisica Γ, Ζ e Η. La paginazione è tuttora usata nelle citazioni scientifiche."}], keyTerms: [{"term":"to on","explanation":"L'essente in greco; tema della riflessione ontologica."},{"term":"einai","explanation":"Verbo essere, le cui funzioni variano nei testi greci."},{"term":"ousia","explanation":"Sostanza o essenza in Aristotele e nelle successive tradizioni."},{"term":"esse","explanation":"Essere in latino, centrale nelle metafisiche medievali."},{"term":"wujūd","explanation":"Esistenza nella filosofia araba, articolata in modo specifico da Avicenna."}], editorialStatus:"edizione editoriale 1.0" },
  { slug:"virtu", id:"CON-000006", kind:"concetto", title:"Virtù", subtitle:"Eccellenza, disposizione e formazione del carattere", area:"Comparativo · tradizioni etiche", period:"Concetto plurale, elaborato in epoche e culture diverse", summary:"La virtù indica, in diverse tradizioni, forme di eccellenza o disposizioni che orientano l'agire; i significati variano e non sono riducibili a un modello universale.", sections:[
    {heading:"Significati e contesti",paragraphs:["Nell'etica greca aretē può indicare l'eccellenza propria di una persona o di una capacità. In Aristotele le virtù etiche sono disposizioni formate dall'abitudine e connesse alla scelta; in Platone il tema si lega anche all'ordine dell'anima e della città.","Nella tradizione confuciana la coltivazione morale si esprime attraverso concetti come ren e de, che non sono traduzioni perfette della virtù greca."]},
    {heading:"Problemi filosofici",paragraphs:["Le teorie della virtù interrogano il rapporto tra carattere e azione, educazione e abitudine, individuo e comunità, conoscenza e pratica. Alcune tradizioni privilegiano l'equilibrio delle disposizioni, altre la relazione, il rito o la disciplina spirituale.","La comparazione deve precisare quali qualità, pratiche e finalità siano effettivamente in gioco."]},
    {heading:"Confronti e cautele",paragraphs:["Aretē, ren e altri termini possono essere messi in dialogo come risposte a problemi morali, ma non sono sinonimi. Occorre evitare di proiettare su ogni tradizione la moderna idea individualistica di carattere."]}
  ,{heading:"Questioni interpretative e approfondimento",paragraphs:["Aretē, virtus e i termini resi con “virtù” non coincidono perfettamente. In Aristotele la virtù etica è una disposizione acquisita e guidata dalla ragione pratica, non una media aritmetica. Nel confucianesimo de indica efficacia morale esemplare; nello stoicismo la virtù è il bene sufficiente alla felicità. Il confronto deve dichiarare tradizione, termine e problema: “virtù” è una categoria comparativa da verificare."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["Per comprendere la virtù aristotelica occorre collegare Etica Nicomachea II, sulla formazione delle disposizioni, VI, sulla saggezza pratica, e X, sulla felicità e la vita contemplativa. La virtù non è soltanto una qualità interiore: si forma attraverso abitudini, educazione e pratiche condivise. La sua applicazione richiede discernimento e non può essere sostituita da un algoritmo di regole.","Il confronto con lo stoicismo mostra una differenza sostanziale: per gli Stoici la virtù è l'unico bene in senso rigoroso, mentre Aristotele riconosce un ruolo costitutivo anche a beni esterni nella vita felice. Il confronto con il confucianesimo deve invece concentrarsi sulle pratiche relazionali e rituali, evitando di tradurre de o ren come semplici sinonimi di aretē."]}], thoughtAnalysis:["Aretē, spesso tradotta con virtù, significa eccellenza o capacità di svolgere bene una funzione. In Platone e Aristotele riguarda la formazione dell’anima e la vita buona. Per Aristotele le virtù si acquisiscono con l’abitudine e si manifestano in scelte appropriate; la saggezza pratica giudica le circostanze. La virtù non è semplice obbedienza a regole, ma disposizione che coinvolge desideri, emozioni e deliberazione. Le nozioni confuciane di ren e yi offrono un confronto relazionale, non una perfetta equivalenza.","Una storia comparata deve chiedere che cosa renda buona una disposizione, come si formi e come si rapporti a felicità e bene comune. Gli stoici identificano la virtù con l’unico bene autentico; altre tradizioni articolano l’eccellenza attraverso doveri, pratiche e relazioni. Il confronto è valido quando rende visibili analogie e differenze, senza presupporre una nozione universale già definita."], tags:["etica","Grecia","Cina","confucianesimo","formazione morale"], related:[{label:"Aristotele",slug:"aristotele",relation:"analisi delle virtù etiche e dianoetiche"},{label:"Confucio",slug:"confucio",relation:"coltivazione morale e pratica rituale"}], bibliography:[{label:"Aristotele, Nicomachean Ethics, trad. e cura di Terence Irwin, 2ª ed., Hackett, 1999.",type:"Testo primario / traduzione",note:"Edizione con introduzione e note per lo studio della virtù, dell’abitudine e della scelta nell’etica aristotelica."},{label:"Confucio, Analects: With Selections from Traditional Commentaries, trad. e cura di Edward Slingerland, Hackett, 2003.",type:"Testo primario / traduzione",note:"Fonte primaria tradotta e contestualizzata per i concetti confuciani di formazione morale, benevolenza e ritualità."},{label:"Aristotele, Ethica Nicomachea, a cura di I. Bywater, Oxford Classical Texts, Clarendon Press, 1894.",type:"Edizione critica / testimone",note:"Edizione del testo greco, utile per controllare il lessico di aretē e le distinzioni tra virtù etiche e dianoetiche; da affiancare a una traduzione commentata."},{label:"Confucio, Dialoghi, trad. e cura di Tiziana Lippiello, Einaudi, 2006.",type:"Testo primario / traduzione",note:"Edizione italiana con testo cinese a fronte; consente di studiare ren e li nel loro contesto, senza tradurli automaticamente con 'virtù' e 'rito' in senso greco."}], keyTerms: [{"term":"aretē","explanation":"Eccellenza o virtù nella filosofia greca; non coincide sempre con la virtù morale moderna."},{"term":"hexis","explanation":"Disposizione stabile acquisita, importante nell'etica aristotelica."},{"term":"phronesis","explanation":"Saggezza pratica, capacità di deliberare bene."},{"term":"ren (仁)","explanation":"Benevolenza confuciana, accostabile con cautela alla virtù greca."},{"term":"guṇa","explanation":"Qualità o attributo nelle tradizioni indiane; non traduce univocamente aretē."}], editorialStatus:"edizione editoriale 1.0" }
,
  {"slug":"dialoghi","id":"OPE-000001","kind":"opera","title":"Dialoghi (Lunyu)","subtitle":"Detti, conversazioni e memoria della tradizione confuciana","area":"Cina","period":"Stratificazione testuale tra epoca pre-imperiale e prima età imperiale","summary":"Raccolta di detti e conversazioni attribuiti a Confucio e ai suoi discepoli, formatasi attraverso una storia redazionale complessa.","sections":[{"heading":"Formazione e struttura","paragraphs":["I Lunyu, noti in italiano come Dialoghi o Analecta, raccolgono brevi conversazioni, massime e scene di insegnamento. Non sono una biografia continua né la trascrizione stenografica delle parole di un singolo maestro.","La forma frammentaria e dialogica richiede di leggere i passi nel loro contesto e di considerare la storia della trasmissione e delle edizioni."]},{"heading":"Temi filosofici","paragraphs":["Ricorrono l'apprendimento, la formazione del carattere, la relazione tra maestro e discepolo, i riti, la benevolenza e la responsabilità di chi governa. Il sapere è presentato anche come pratica e trasformazione di sé.","La traduzione di termini come ren e li richiede cautela: le equivalenze moderne non restituiscono da sole la densità storica dei concetti."]},{"heading":"Ricezione","paragraphs":["I Lunyu divennero un testo fondamentale dell'educazione e della cultura politica dell'Asia orientale. Commentari e sistemi scolastici ne hanno orientato la lettura in epoche diverse."]},{heading:"Questioni interpretative e approfondimento",paragraphs:["I Lunyu sono venti libri di detti, scene e risposte attribuiti a Confucio e ai discepoli, non una biografia né un’esposizione sistematica. Studio, rito, governo e coltivazione morale ritornano in contesti diversi. Il testo trasmesso ha una storia complessa, con varianti e commentari; le scelte di traduzione di ren, li, junzi e dao orientano l’interpretazione. Conviene confrontare più versioni e distinguere testo e commentari."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["La numerazione in venti libri è diventata uno strumento standard per citare i passi, ma non dimostra che la raccolta sia stata composta in un'unica fase. Le differenze tra recensioni e le testimonianze manoscritte invitano a distinguere la storia del testo dalla ricostruzione della vita di Confucio. La forma breve dei detti lascia spesso aperte questioni interpretative che i commentari hanno cercato di risolvere.","Per leggere i Lunyu in modo comparativo è utile seguire alcuni nuclei: apprendimento e memoria, rito e gerarchia, benevolenza e reciprocità, governo mediante esempio. Il confronto con Mengzi e Xunzi mostra come temi presenti nei Dialoghi siano stati sviluppati in direzioni divergenti. Le traduzioni dovrebbero essere confrontate sul lessico cinese, soprattutto quando un termine ricorre in contesti diversi."]}],thoughtAnalysis:["I Dialoghi (Lunyu) sono una raccolta stratificata di detti e conversazioni attribuiti a Confucio e ai discepoli, non una trascrizione stenografica né un trattato unitario. Il significato delle risposte dipende spesso dalla domanda e dall’interlocutore. La forma frammentaria è quindi parte del contenuto filosofico: mostra un insegnamento situato e una comunità che conserva e interpreta la memoria del maestro.","La lettura richiede attenzione alla redazione, alle varianti e ai commentari. Ren, li, yi e junzi si comprendono attraverso esempi e relazioni, non come definizioni isolate. La canonizzazione imperiale trasformò il testo in riferimento educativo e politico. Il confronto con Mengzi e Xunzi mostra che il confucianesimo si sviluppò attraverso controversie sulla natura umana, i riti e l’educazione."], "tags":["Cina","confucianesimo","testo classico","etica","educazione"],"related":[{"label":"Confucio","slug":"confucio","relation":"figura centrale associata alla raccolta"},{"label":"Virtù","slug":"virtu","relation":"problemi della formazione morale"}],"bibliography":[{"label":"Confucio, Analects: With Selections from Traditional Commentaries, trad. e cura di Edward Slingerland, Hackett, 2003.","type":"Testo primario / traduzione","note":"Traduzione annotata con selezioni di commentari tradizionali, glossario e bibliografia ragionata; utile per la storia della trasmissione e dell’interpretazione dei Lunyu. Edizione italiana: Confucio, Dialoghi, traduzione e cura di Tiziana Lippiello, Einaudi, 2006, con testo cinese a fronte."}], keyTerms: [{"term":"lun (論)","explanation":"Discussione o esposizione ragionata, componente del titolo Lunyu."},{"term":"yu (語)","explanation":"Detti o conversazioni, riferiti alla forma della raccolta."},{"term":"ren (仁)","explanation":"Benevolenza, nozione ricorrente nei dialoghi."},{"term":"li (禮)","explanation":"Ritualità e forme appropriate della relazione."},{"term":"junzi (君子)","explanation":"Persona esemplare, formata da studio e pratica."}], works: [{"title":"Lunyu","note":"Raccolta stratificata di conversazioni e detti; non verbale stenografico del maestro."},{"title":"Mengzi","note":"Testo successivo che sviluppa temi confuciani, incluso il dibattito sulla natura umana."},{"title":"Xunzi","note":"Opera di una corrente confuciana successiva, critica verso la spontaneità non educata."}], timeline: [{"date":"V–III secolo a.C.","event":"Formazione progressiva dei materiali dei Lunyu."},{"date":"II secolo a.C.","event":"Stabilizzazione e canonizzazione in età Han, con varianti testuali."},{"date":"Età imperiale","event":"Commentari e uso educativo del testo in contesti istituzionali."}], "editorialStatus":"edizione editoriale 1.0"},
  {"slug":"stoicismo","id":"SCU-000001","kind":"scuola","title":"Stoicismo","subtitle":"Logica, fisica ed etica come esercizio di vita","area":"Grecia e mondo romano","period":"Dal III secolo a.C. all'età imperiale, con riprese successive","summary":"Tradizione filosofica fondata ad Atene da Zenone di Cizio, sviluppatasi in più fasi e caratterizzata dall'integrazione di logica, fisica ed etica.","sections":[{"heading":"Origini e sviluppo","paragraphs":["Lo stoicismo nasce ad Atene intorno all'insegnamento di Zenone di Cizio e si sviluppa attraverso la Stoa antica, media e romana. Le opere dei primi Stoici sono in gran parte perdute e sono conosciute attraverso testimonianze e citazioni posteriori.","Non si tratta di una dottrina immutabile: scuole, autori e contesti storici hanno prodotto accenti e interpretazioni differenti."]},{"heading":"Architettura filosofica","paragraphs":["La filosofia stoica è spesso articolata in logica, fisica ed etica, discipline considerate connesse. La fisica indaga un cosmo ordinato e corporeo; la logica studia il ragionamento e il linguaggio; l'etica riflette sulla virtù e sulla vita conforme alla natura.","Nella riflessione etica hanno rilievo il giudizio, il consenso alle rappresentazioni e la distinzione tra ciò che dipende da noi e ciò che non dipende da noi, formulata con accenti diversi dagli autori."]},{"heading":"Ricezione e confronti","paragraphs":["La tradizione stoica influenzò profondamente la filosofia romana e fu ripresa in età moderna e contemporanea. Le letture attuali devono distinguere i testi antichi dalle reinterpretazioni moderne, spesso selettive."]},{heading:"Questioni interpretative e approfondimento",paragraphs:["Logica, fisica ed etica sono parti interdipendenti: la logica studia linguaggio e inferenze, la fisica un cosmo corporeo ordinato, l’etica la vita conforme alla natura. Gli indifferenti non sono irrilevanti: salute e condizioni materiali possono essere preferibili, pur non costituendo il bene morale. Epitteto, Seneca e Marco Aurelio appartengono a fasi e generi diversi e non esauriscono lo stoicismo antico."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["La conoscenza dello stoicismo antico dipende in larga parte da testimonianze indirette, citazioni polemiche e compendi posteriori. Occorre quindi distinguere la dottrina dei fondatori dalle elaborazioni della Stoa media e dagli scritti imperiali. Le opere di Seneca, Epitteto e Marco Aurelio sono fonti essenziali per la ricezione romana, ma non restituiscono da sole l'intero sistema ellenistico.","La pratica etica stoica comprende esercizi di esame dei giudizi, attenzione alle rappresentazioni e riflessione sulla comunità umana. La formula moderna “ciò che dipende da noi” è particolarmente associata a Epitteto e non va usata come sintesi indifferenziata di ogni autore stoico. La voce dovrebbe distinguere etica antica, appropriazioni moderne e divulgazione contemporanea."]}],thoughtAnalysis:["Lo stoicismo unisce logica, fisica ed etica: la logica studia ragionamento e giudizio, la fisica descrive il cosmo razionale permeato dal logos, l’etica ricerca una vita secondo natura. Le tre parti si sostengono reciprocamente. La dottrina dell’assenso sottolinea che non siamo passivamente determinati dalle impressioni: il giudizio con cui le approviamo è decisivo per la responsabilità morale.","La virtù è l’unico bene autentico; salute e ricchezza sono indifferenti, pur potendo essere preferibili. Le passioni sono giudizi e impulsi disordinati, non semplici emozioni da reprimere. Vivere secondo natura significa riconoscersi parte del cosmo e della comunità umana, da cui derivano cosmopolitismo e doveri verso gli altri. La scuola ebbe sviluppi diversi da Zenone e Crisippo fino agli autori romani."], "tags":["Grecia","Roma","etica","logica","fisica"],"related":[{"label":"Logos (λόγος)","slug":"logos","relation":"concetto centrale in diverse formulazioni stoiche"},{"label":"Virtù","slug":"virtu","relation":"eccellenza morale e pratica etica"}],"bibliography":[{"label":"A. A. Long e D. N. Sedley, The Hellenistic Philosophers, 2 voll., Cambridge University Press, 1987.","type":"Testo primario / traduzione","note":"Raccolta fondamentale di fonti greche e latine, traduzioni, commenti filosofici e bibliografia; consente di distinguere le diverse fasi dello stoicismo."},{"label":"Brad Inwood (a cura di), The Cambridge Companion to the Stoics, Cambridge University Press, 2003.","type":"Studio secondario","note":"Volume collettivo di studi specialistici sui principali temi e autori della tradizione stoica. Per una raccolta italiana dei frammenti: Stoici antichi, a cura di Margherita Isnardi Parente, UTET, 1989, 2 voll."}], keyTerms: [{"term":"logos","explanation":"Principio razionale e corporeo che struttura il cosmo secondo gli stoici."},{"term":"pneuma","explanation":"Soffio corporeo e tensione organizzatrice della realtà."},{"term":"oikeiōsis","explanation":"Processo di appropriazione e ampliamento delle relazioni morali."},{"term":"apatheia","explanation":"Libertà dalle passioni intese come giudizi disordinati, non insensibilità."},{"term":"kathēkon","explanation":"Azione appropriata o dovere conveniente."}], works: [{"title":"Frammenti di Zenone, Cleante e Crisippo","note":"Opere in gran parte perdute, ricostruibili attraverso testimonianze e citazioni."},{"title":"Diatribe di Epitteto","note":"Discorsi conservati grazie alla redazione di Arriano."},{"title":"Manuale di Epitteto","note":"Compendio di insegnamenti etici."},{"title":"Lettere a Lucilio di Seneca","note":"Testo latino fondamentale per la ricezione romana dello stoicismo."},{"title":"Pensieri di Marco Aurelio","note":"Scrittura personale e filosofica di età imperiale."}], timeline: [{"date":"III secolo a.C.","event":"Fondazione della scuola ad Atene da parte di Zenone di Cizio."},{"date":"III–II secolo a.C.","event":"Sviluppo della Stoa antica con Cleante e Crisippo."},{"date":"I secolo a.C.–I secolo d.C.","event":"Rielaborazione romana e imperiale dello stoicismo."},{"date":"I–II secolo d.C.","event":"Epitteto e Marco Aurelio, figure della ricezione imperiale."}], "editorialStatus":"edizione editoriale 1.0"},
  {"slug":"madhyamaka","id":"SCU-000002","kind":"scuola","title":"Madhyamaka","subtitle":"La via di mezzo e la critica dell'esistenza intrinseca","area":"India","period":"Dai primi secoli dell'era comune; sviluppi in Asia","summary":"Tradizione filosofica buddhista mahāyāna associata all'analisi della vacuità e dell'origine dipendente, sviluppata attraverso dibattiti e commentari.","sections":[{"heading":"Origini e contesto","paragraphs":["Il Madhyamaka si forma nel contesto del buddhismo mahāyāna indiano ed è legato soprattutto alle opere attribuite a Nāgārjuna e ai successivi commentatori. La ricostruzione delle origini richiede attenzione alla pluralità dei testi e delle linee interpretative.","La denominazione 'via di mezzo' va compresa in rapporto ai dibattiti buddhisti sulle posizioni estreme e sulle pretese di fondazione ontologica."]},{"heading":"Problemi e argomenti","paragraphs":["L'analisi madhyamaka esamina criticamente la pretesa che persone e fenomeni possiedano natura propria indipendente. La vacuità non è una sostanza nascosta né una tesi secondo cui nulla esiste: è connessa al sorgere dipendente e all'analisi delle designazioni convenzionali.","Le diverse scuole madhyamaka hanno elaborato metodi argomentativi e interpretazioni non identici. È quindi necessario specificare autori, testi e contesti quando si presenta una tesi."]},{"heading":"Diffusione e ricezione","paragraphs":["Il Madhyamaka ebbe sviluppi importanti in India, Tibet e Asia orientale. Le traduzioni, i commentari e le controversie locali hanno contribuito a trasformarne il lessico e le strategie filosofiche."]},{heading:"Questioni interpretative e approfondimento",paragraphs:["Il Madhyamaka non è monolitico: le interpretazioni di Nāgārjuna, Āryadeva, Buddhapālita, Bhāviveka e Candrakīrti differiscono per metodi e tesi. Le classificazioni successive come Svātantrika e Prāsaṅgika hanno una storia esegetica specifica. La critica delle concezioni sostanzialiste è connessa alla pratica buddhista e al superamento dell’attaccamento. Ogni esposizione deve specificare testi, linea interpretativa e ricezione regionale."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["Per orientarsi nella storia indiana della scuola è utile distinguere Nāgārjuna e Āryadeva dai commentatori successivi. Buddhapālita, Bhāviveka e Candrakīrti sono associati a differenti strategie esegetiche e argomentative; le etichette scolastiche con cui vengono classificati si consolidarono anche nelle tradizioni tibetane. Le genealogie dottrinali non vanno trattate come tassonomie neutrali e senza storia.","La diffusione in Tibet e in Asia orientale produsse lessici, curricula e controversie differenti. Una presentazione globale deve distinguere la storia indiana del Madhyamaka dalle sue ricezioni regionali, indicando quando una classificazione è emica, cioè usata da una tradizione, e quando è una categoria storiografica moderna."]}],thoughtAnalysis:["Il Madhyamaka è una tradizione buddhista che usa la vacuità per criticare ogni pretesa di esistenza intrinseca. Poiché i fenomeni sorgono in dipendenza da cause, condizioni e parti, non possono essere fondamenti autonomi. Nāgārjuna analizza causalità, movimento, identità e tempo; la scuola non propone una nuova sostanza chiamata vacuità, ma mette in discussione la reificazione di ogni posizione.","La tradizione comprende commentatori indiani, sviluppi tibetani e ricezioni in Asia orientale. Buddhapālita, Bhāviveka e Candrakīrti sono associati a strategie differenti; le classificazioni Prāsaṅgika e Svātantrika hanno una storia complessa. Le due verità chiariscono il rapporto fra funzionamento convenzionale e comprensione ultima. La finalità è anche pratica: ridurre attaccamento, avversione e ignoranza."], "tags":["India","buddhismo","mahāyāna","vacuità","origine dipendente"],"related":[{"label":"Nāgārjuna","slug":"nagarjuna","relation":"autore fondamentale della tradizione"},{"label":"Śūnyatā (vacuità)","slug":"sunyata","relation":"concetto centrale"}],"bibliography":[{"label":"Nāgārjuna, The Fundamental Wisdom of the Middle Way, trad. e commento di Jay L. Garfield, Oxford University Press, 1995.","type":"Testo primario / traduzione","note":"Edizione di riferimento per il testo fondamentale del Madhyamaka. Si affianchi la traduzione italiana di Nāgārjuna, Madhyamaka kārikā; Vigraha vyāvartanī; Catuḥstava, a cura di Raniero Gnoli, Boringhieri, 1961."},{"label":"Jan Westerhoff, Nāgārjuna’s Madhyamaka: A Philosophical Introduction, Oxford University Press, 2009.","type":"Studio secondario","note":"Studio introduttivo sulle argomentazioni, le interpretazioni e i problemi filosofici della scuola."}], keyTerms: [{"term":"śūnyatā","explanation":"Vacuità di esistenza intrinseca, connessa all'origine dipendente."},{"term":"prāsaṅga","explanation":"Procedimento che mostra le conseguenze indesiderate delle tesi avversarie."},{"term":"svātantra","explanation":"Inferenza autonoma, centrale in alcune classificazioni esegetiche tibetane."},{"term":"dve satye","explanation":"Due verità, convenzionale e ultima, articolate in modi differenti dai commentatori."},{"term":"prajñā","explanation":"Sapienza che comprende la vacuità senza reificarla."}], works: [{"title":"Mūlamadhyamakakārikā","note":"Testo fondativo associato a Nāgārjuna."},{"title":"Catuḥśataka","note":"Opera di Āryadeva, importante per lo sviluppo della scuola."},{"title":"Prasannapadā","note":"Commentario di Candrakīrti alle Stanze fondamentali."},{"title":"Madhyamakāvatāra","note":"Introduzione al Madhyamaka di Candrakīrti."}], timeline: [{"date":"II–III secolo d.C.","event":"Attività di Nāgārjuna, collocazione approssimativa."},{"date":"III–IV secolo d.C.","event":"Āryadeva e primi sviluppi della tradizione."},{"date":"V–VI secolo d.C.","event":"Dibattiti esegetici di Buddhapālita e Bhāviveka."},{"date":"VII secolo d.C.","event":"Candrakīrti e la successiva ricezione delle sue interpretazioni."},{"date":"VII–XI secolo d.C.","event":"Trasmissioni e rielaborazioni in Tibet, in più fasi."}], "editorialStatus":"edizione editoriale 1.0"},
  {"slug":"eta-assiale","id":"PER-000001","kind":"periodo","title":"Età assiale","subtitle":"Una categoria interpretativa per trasformazioni intellettuali antiche","area":"Comparativo · Eurasia","period":"Convenzionalmente circa 800–200 a.C.","summary":"L'espressione 'età assiale' indica una tesi storiografica sulle trasformazioni religiose e filosofiche avvenute in diverse regioni dell'Eurasia antica; la categoria è discussa e non va intesa come cronologia universale condivisa.","sections":[{"heading":"La proposta storiografica","paragraphs":["La nozione è associata al filosofo e storico Karl Jaspers, che individuò in un arco di secoli trasformazioni profonde in Cina, India, Iran, Israele e Grecia. La proposta ha avuto grande influenza nel dibattito sulla storia globale delle idee.","Non è un periodo storico unitario riconosciuto da tutte le discipline: è una cornice interpretativa, con limiti cronologici e geografici contestati."]},{"heading":"Potenzialità e limiti","paragraphs":["La categoria invita a studiare comparativamente nuove forme di riflessione etica, cosmologica e politica, nonché il rapporto tra tradizioni orali, scrittura e istituzioni.","Il rischio è appiattire differenze, suggerire sviluppi simultanei non dimostrati o costruire una narrazione teleologica centrata su pochi canoni. Le cronologie regionali e le prove documentarie devono restare prioritarie."]},{"heading":"Uso nel dizionario","paragraphs":["Nel repertorio questa voce funziona come strumento di orientamento storiografico, non come contenitore che rende equivalenti Confucio, le Upaniṣad, i profeti israeliti e i pensatori greci.","Ogni confronto dovrà dichiarare il criterio adottato e distinguere convergenze, contatti storici e analogie formulate dallo studioso."]},{heading:"Questioni interpretative e approfondimento",paragraphs:["L’età assiale è una categoria storiografica, non un periodo universalmente riconosciuto. Il confronto tra Cina, India, Iran, Israele e Grecia dipende dai criteri adottati: trasformazioni morali, tradizioni scritte, critica rituale o nuove concezioni politiche. Le cronologie regionali non coincidono. La categoria resta utile come ipotesi da verificare, purché ogni confronto dichiari fonti, unità di analisi e possibili contatti."]},{heading:"Testi, controversie e piste di ricerca",paragraphs:["La proposta di Jaspers nasce in un contesto intellettuale europeo del Novecento e va letta come modello interpretativo, non come descrizione neutrale di un'epoca universalmente riconosciuta. Le ricerche successive hanno discusso sia la selezione geografica sia l'idea di una trasformazione simultanea. È utile chiedere quali indicatori rendano comparabili fenomeni tanto diversi: nuove forme di autorità, scrittura, riflessività morale o organizzazione politica.","Un uso responsabile della categoria deve includere anche ciò che essa lascia fuori: Africa, Americhe, società senza tradizioni testuali conservate e processi che non rientrano nella cronologia convenzionale. La comparazione globale non deve diventare una classifica di civiltà né una storia unica del “risveglio” umano. Le differenze regionali e le asimmetrie delle fonti sono parte del risultato, non ostacoli da eliminare."]}],thoughtAnalysis:["L’età assiale è una tesi storiografica formulata da Karl Jaspers per interpretare trasformazioni intellettuali in Cina, India, Iran, Israele e Grecia. La categoria cerca di cogliere nuove forme di riflessività morale, critica delle consuetudini e interrogazione sul senso dell’esistenza. Non designa un’epoca universalmente riconosciuta, né dimostra che i processi siano stati identici o simultanei. È una cornice comparativa da sottoporre a verifica.","Le obiezioni riguardano selezione geografica, cronologia e privilegio delle tradizioni scritte. Molte società restano fuori dal quadro e le fonti sono distribuite in modo diseguale. Un uso responsabile deve dichiarare gli indicatori comparati: autorità morali, pratiche testuali, istituzioni o concezioni cosmologiche. Le differenze regionali sono parte del risultato, non ostacoli da cancellare. La categoria è un’ipotesi di ricerca, non una legge universale."], "tags":["storiografia","comparazione","Cina","India","Grecia","Eurasia"],"related":[{"label":"Confucio","slug":"confucio","relation":"figura spesso collocata nel quadro cronologico della categoria"},{"label":"Nāgārjuna","slug":"nagarjuna","relation":"cronologicamente successivo alla fascia classica convenzionale"}],"bibliography":[{"label":"Karl Jaspers, The Origin and Goal of History, trad. di Michael Bullock, Yale University Press, 1953 (originale tedesco 1949).","type":"Testo primario / traduzione","note":"Testo in cui Jaspers formula la categoria moderna di età assiale; va letto come proposta interpretativa, non come periodizzazione universalmente accettata."},{"label":"Robert N. Bellah e Hans Joas (a cura di), The Axial Age and Its Consequences, Harvard University Press, 2012.","type":"Studio secondario","note":"Raccolta di saggi che riprende criticamente la tesi assiale e ne discute portata, limiti e conseguenze comparative."}], keyTerms: [{"term":"Achsenzeit","explanation":"Espressione tedesca con cui Jaspers designa il periodo assiale."},{"term":"comparazione storica","explanation":"Metodo che confronta processi senza presupporre identità o contatti."},{"term":"sincronia","explanation":"Coincidenza temporale da verificare, non da dedurre dalla categoria."},{"term":"canone","explanation":"Selezione di testi e figure che condiziona la narrazione globale."},{"term":"storiografia globale","explanation":"Approccio che esamina anche esclusioni e asimmetrie delle fonti."}], works: [{"title":"Vom Ursprung und Ziel der Geschichte","note":"Opera di Karl Jaspers (1949) che formula la categoria dell'età assiale."},{"title":"The Axial Age and Its Consequences","note":"Volume collettivo curato da Robert N. Bellah e Hans Joas (2012), di discussione critica."}], timeline: [{"date":"circa 800–200 a.C.","event":"Intervallo convenzionale proposto da Jaspers, non periodizzazione condivisa."},{"date":"1949","event":"Pubblicazione dell'opera di Jaspers che formula la tesi."},{"date":"2012","event":"Pubblicazione di una raccolta influente di ripresa critica del dibattito."}], "editorialStatus":"edizione editoriale 1.0"}
];


